def logger(func):
    def wrapper():
        print(f'Вызов {func.__name__}')
        return func()
    return wrapper

@logger
def encrypt():
    print('Данные зашифрованы')

encrypt()  # Вызов encrypt\nДанные зашифрованы

def repeat(func):
    def wrapper():
        func()
        func()
    return wrapper

@repeat
def say_hi():
    print('Привет')

say_hi()  # Привет\nПривет

