def logger(func):
    def wrapper(*args, **kwargs):
        print(f'Вызов {func.__name__}')
        return func(*args, **kwargs)
    return wrapper

@logger
def greet(name, greeting='Привет'):
    return f'{greeting}, {name}'

print(greet('V'))  # Вызов greet\nПривет, V

import functools


def logger(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

@logger
def encrypt():
    """Шифрует данные."""
    pass

print(encrypt.__name__)  # encrypt (спасено functools.wraps)

