class Counter:
    def __init__(self, func):
        self.func = func
        self.calls = 0
    def __call__(self, *args, **kwargs):
        self.calls += 1
        return self.func(*args, **kwargs)

@Counter
def greet():
    return 'Привет'

print(greet())     # Привет
print(greet.calls)  # 1

